-- 地标种子：26 个世界地标的完整数据。
-- 字段：target_id（英文标识，同时是百科图片文件名）/ name（中文名）/ name_en（英文名）/
--       region（大区）/ country（国家）/ lat（纬度）/ lon（经度）/ intro（百科介绍）。
-- 由 `python backend/manage.py init_tripscape` 解析写入 Landmark 表；
-- 百科图片按 /static/landmarks/<target_id>.jpg 约定自动关联。
-- 新增地标：按下方格式追加一行 INSERT 元组即可，无需改任何代码。

INSERT INTO landmarks (target_id, name, name_en, region, country, lat, lon, intro) VALUES

('AbuSimbelTemples', '阿布辛贝神庙', 'AbuSimbelTemples', '非洲', '埃及', 22.337, 31.626, '古埃及法老拉美西斯二世的惊世之作，直接在尼罗河西岸的整座山体中开凿而成。正面是四尊高达20米的法老坐像，每年2月22日和10月22日初升太阳会穿过60米深的殿堂照亮神龛，即著名的“太阳节”奇观。1960年代因阿斯旺大坝建设整体切割搬迁至高处。'),
('AngelFalls', '安赫尔瀑布', 'AngelFalls', '南美洲', '委内瑞拉', 5.967, -62.536, '世界上落差最大的瀑布，总落差979米，位于委内瑞拉圭亚那高原的奥扬特普伊山。以飞行员吉米·安赫尔命名，藏身于原始雨林之中，雨季水量充沛时气势磅礴。'),
('BentPyramid', '弯曲金字塔', 'BentPyramid', '非洲', '埃及', 29.790, 31.215, '古埃及第四王朝法老斯尼夫鲁建造的金字塔，因建造过程中倾角从54度改为43度而呈现独特的弯曲外观，是金字塔建造技术演进的重要见证。'),
('BurjKhalifa', '哈利法塔', 'BurjKhalifa', '亚洲', '阿联酋', 25.197, 55.274, '世界第一高楼，高828米，共163层，位于迪拜。2010年落成，外观如沙漠之花蜘蛛兰的对称结构，拥有世界最高的观景台。'),
('ChichenItza', '奇琴伊察', 'ChichenItza', '北美洲', '墨西哥', 20.683, -88.567, '玛雅文明最著名的城邦遗址，位于墨西哥尤卡坦半岛。库库尔坎金字塔在春秋分时会形成“羽蛇神下凡”的光影奇观，1988年列入世界文化遗产。'),
('ChristTheRedeemer', '救世基督像', 'ChristTheRedeemer', '南美洲', '巴西', -22.951, -43.211, '矗立于里约热内卢科尔科瓦多山顶的巨型基督雕像，高38米，双臂展开28米，1931年落成，是里约最著名的地标与巴西的象征。'),
('DjoserPyramid', '左塞尔金字塔', 'DjoserPyramid', '非洲', '埃及', 29.871, 31.216, '埃及最古老的阶梯金字塔，建于约公元前2670年，由宰相伊姆霍特普为法老左塞尔设计，是埃及金字塔建造的开端。'),
('EiffelTower', '埃菲尔铁塔', 'EiffelTower', '欧洲', '法国', 48.858, 2.294, '建于1889年巴黎世界博览会的铁塔，高330米，由古斯塔夫·埃菲尔的公司设计建造。曾是世界最高建筑41年，现每年迎接数百万游客。'),
('GizaPyramids', '吉萨金字塔群', 'GizaPyramids', '非洲', '埃及', 29.979, 31.134, '位于开罗近郊，包括胡夫金字塔、哈夫拉金字塔与门卡乌拉金字塔，以及狮身人面像。胡夫金字塔是古代世界七大奇迹中唯一现存者。'),
('GreatWall', '长城', 'GreatWall', '亚洲', '中国', 40.358, 116.024, '中国古代军事防御工程，东起山海关西至嘉峪关，全长两万多公里。始建于春秋战国，明代大规模重建，1987年列入世界文化遗产。'),
('HatshepsutTemples', '哈特谢普苏特神庙', 'HatshepsutTemples', '非洲', '埃及', 25.738, 32.606, '古埃及女法老哈特谢普苏特的陵庙，三层柱廊式建筑依山而建，气势恢宏，位于卢克索尼罗河西岸。'),
('HeavenTemple', '天坛', 'HeavenTemple', '亚洲', '中国', 39.882, 116.406, '明清两代皇帝祭天祈谷的坛庙，位于北京。祈年殿三重檐攒尖顶是中国古建的巅峰之作，1998年列入世界文化遗产。'),
('Huangguoshu', '黄果树瀑布', 'Huangguoshu', '亚洲', '中国', 25.993, 105.666, '中国最大的瀑布，位于贵州安顺，高77.8米，宽101米。瀑布后的水帘洞可从洞内观瀑，徐霞客曾盛赞其“珠帘钩不卷”。'),
('Leifeng', '雷峰塔', 'Leifeng', '亚洲', '中国', 30.233, 120.151, '位于杭州西湖夕照山，因《白蛇传》中法海镇压白娘子的传说而闻名。原塔1924年倒塌，2002年在原址重建。'),
('LibertyStatue', '自由女神像', 'LibertyStatue', '北美洲', '美国', 40.689, -74.045, '法国赠送给美国的独立礼物，1886年落成于纽约港自由岛。高93米（含基座），是自由与民主的象征。'),
('MachuPicchu', '马丘比丘', 'MachuPicchu', '南美洲', '秘鲁', -13.163, -72.545, '印加帝国的“失落之城”，海拔2430米，坐落于安第斯山脉的山脊上。15世纪建造，1911年被重新发现，1983年列入世界文化遗产。'),
('MemnonColossi', '门农巨像', 'MemnonColossi', '非洲', '埃及', 25.719, 32.612, '两座高18米的巨型石像，原是新王国法老阿蒙霍特普三世祭庙前的雕像。罗马时期清晨会发出鸣响，被称为“会唱歌的门农”。'),
('Petra', '佩特拉', 'Petra', '亚洲', '约旦', 30.329, 35.444, '纳巴泰王国的都城，整座城市在玫瑰色岩壁上开凿而成，卡兹尼神殿最为著名。1985年列入世界文化遗产。'),
('Potala', '布达拉宫', 'Potala', '亚洲', '中国', 29.658, 91.117, '坐落于拉萨红山之上的宫堡式建筑群，始建于公元7世纪松赞干布时期。红宫与白宫依山垒砌，是藏传佛教的圣地。'),
('Qomolangma', '珠穆朗玛峰', 'Qomolangma', '亚洲', '中国/尼泊尔', 27.988, 86.925, '世界最高峰，海拔8848.86米，地处中尼边境。藏语意为“大地之母”，尼泊尔称萨加玛塔峰。'),
('Ramesseum', '拉美西姆神庙', 'Ramesseum', '非洲', '埃及', 25.727, 32.611, '法老拉美西斯二世的祭庙，位于卢克索西岸。曾矗立着重达约1000吨的拉美西斯二世巨型坐像碎片。'),
('RomanColosseum', '罗马斗兽场', 'RomanColosseum', '欧洲', '意大利', 41.890, 12.492, '古罗马最大的圆形角斗场，公元80年落成，可容纳约5万观众。混凝土与拱券技术的巅峰之作，1980年列入世界文化遗产。'),
('Sphinx', '狮身人面像', 'Sphinx', '非洲', '埃及', 29.975, 31.138, '位于吉萨金字塔群旁，高20米长73米，狮身人面，相传面部按法老哈夫拉雕刻。是世界上最著名的纪念雕像之一。'),
('Stonehenge', '巨石阵', 'Stonehenge', '欧洲', '英国', 51.179, -1.826, '位于英格兰索尔兹伯里平原的史前巨石建筑，约建于公元前3000-2000年。环形石阵与天文历法的关联至今成谜。'),
('TajMahal', '泰姬陵', 'TajMahal', '亚洲', '印度', 27.175, 78.042, '莫卧儿皇帝沙贾汗为爱妻泰姬·玛哈尔修建的白色大理石陵墓，1653年建成。对称布局与宝石镶嵌工艺登峰造极。'),
('ThreePagodas', '崇圣寺三塔', 'ThreePagodas', '亚洲', '中国', 25.708, 100.147, '位于云南大理苍山脚下，主塔千寻塔高69.13米，为唐代密檐式砖塔。三塔鼎立，是大理的标志性建筑。');
